HERE=Path(__file__).resolve().parent;PLUGIN=HERE.parent/'figma-plugin';cloud=json.loads((HERE/'state.json').read_text());raw=(PLUGIN/'code.js').read_text();bundle=json.JSONDecoder().raw_decode(raw.split('const BUNDLE = ',1)[1])[0];data=json.loads((HERE.parent/'data/crop-dex.json').read_text());bundle.update(screens=[],cropDexData=data,sceneBytes={},iconSvgs={},iconNodeIds={},assetNames={},flowRepairStates=[],npcFlowStates=[]);bundle['sceneHashes'].update(json.loads((HERE.parent/'data/legacy-scene-hashes.json').read_text())['hashes']);bundle['sceneHashes'].update(cloud.get('sceneHashes',{}));bundle.pop('avatarAssets',None);bundle.pop('avatarControlIcons',None);bundle.pop('freeTravelStates',None);bundle.pop('freeTravelPassport',None)
