state={k:cloud[k] for k in ['pageId','libraryId','variables','styles','kit','icons','overlayIndex']};state['variables']={k:v for k,v in state['variables'].items() if k.startswith(('color/','space/','radius/'))};state['icons']={k:v for k,v in state['icons'].items() if k.startswith(('i-','crop_'))};state['kit']={k:v for k,v in state['kit'].items() if not k.startswith(('Reference','FacilityMarker/','Avatar','NoteSelection/','Compact/Kitchen/','Legacy'))}
