tail='''function cropCreatedIds(){const nodes=PAGE.findAll(()=>true).filter(n=>!beforeIds.has(n.id)),direct=[],suffixes={};for(const n of nodes){const at=n.id.indexOf(';');if(at<0)direct.push(n.id);else(suffixes[n.id.slice(at)]??=[]).push(n.id.slice(0,at));}function ranges(ns){const sorted=[...new Set(ns)].sort((a,b)=>a-b),out=[];let a,b;for(const n of sorted){if(a===undefined)a=b=n;else if(n===b+1)b=n;else{out.push(a===b?String(a):a+'-'+b);a=b=n;}}if(a!==undefined)out.push(a===b?String(a):a+'-'+b);return out.join(',');}const groups=new Map();for(const [suffix,ids]of Object.entries(suffixes)){const values={};for(const id of ids){const [prefix,n]=id.split(':');(values[prefix]??=[]).push(Number(n));}const roots=Object.fromEntries(Object.entries(values).map(([p,ns])=>[p,ranges(ns)])),key=JSON.stringify(roots);if(!groups.has(key))groups.set(key,{roots,suffixes:[]});groups.get(key).suffixes.push(suffix);}return {createdNodeIds:direct,inheritedNodeIdRanges:[...groups.values()],createdNodeCount:nodes.length,idEncoding:'Expand roots prefix:number ranges and append each literal suffix to recover all inherited IDs.'};}
const page=await createCropDex();await wire();await Promise.all(STYLE_JOBS);const cells=page.findAll(n=>n.type==='FRAME'&&n.name.startsWith('Compact/Crop cell ·'));if(cells.length!==20)throw Error('Crop-dex must contain20 genuine crop entries');const checks=page.findAll(n=>n.name==='Harvested check');if(checks.length!==7)throw Error('Crop-dex7/20 fixture is inconsistent');if(!page.findOne(n=>n.type==='INSTANCE'&&n.name==='HUD'))throw Error('Missing collection HUD');return {...cropCreatedIds(),mutatedNodeIds:[],cropDex:{screenId:page.id,entries:cells.map(n=>({id:n.id,title:n.name.slice('Compact/Crop cell · '.length)})),harvested:checks.length,perCropQuantitiesInvented:false},overlayIndex,warnings:LEDGER.warnings,overlays:LEDGER.overlays,sourceReferences:LEDGER.sourceReferences,additionalContentScreen:true};'''
code='const BUNDLE='+json.dumps(bundle,ensure_ascii=False,separators=(',',':'))+';\n'+source+'\n'+restore+'\n'+tail;dest=Path(os.environ.get('GENSEN_CLOUD_OUTPUT',str(HERE/'crop-dex.js')));dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(code);subprocess.run(['node',str(HERE/'minify.cjs'),str(dest)],check=True);subprocess.run(['node',str(HERE/'preflight_script.cjs'),str(dest)],check=True);assert dest.stat().st_size<50000;print(json.dumps({'file':str(dest),'bytes':dest.stat().st_size,'figmaExecuted':False,'stateWritten':False}))
